#!/usr/bin/env python3
import hashlib,json,re
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'docs/research'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=D/'dedup-model-bank-qualified-native-20261011.json';r=json.loads(p.read_text());assert r['status']=='complete_bounded_real_cpu_pixel_qualified_banks' and len(r['results'])==3;assert [(x['baseline_index'],x['window_radius']) for x in r['plan']]==[(255,2),(7,2),(67,6)];pins=dict(r['pins']);assert all(sha(k)==v for k,v in pins.items())
 mp=D/'dedup-model-bank-qualified-candidates-snapshot-20261011.json';m=json.loads(mp.read_text());assert all(sha(Path(m['snapshot'])/k)==v for k,v in m['file_hashes'].items());gp=D/'dedup-model-bank-qualified-candidates-verification-20261011.json';g=json.loads(gp.read_text());assert g['status']=='verified_98_tests_pixel_qualified_bank_candidates';assert all(sha(k)==v for k,v in g['pins'].items())
 runtime=D/'dedup-loftr-native-20261010-runtime-pins.json';rt=json.loads(runtime.read_text());libs={k:v for k,v in rt['pins'].items() if k.endswith('.dylib')};assert libs and all(sha(k)==v for k,v in libs.items());pins.update(libs)
 refs=[D/'dedup-model-bank-native-audit-20261011.json',D/'dedup-model-bank-broader-controls-audit-20261011.json',D/'dedup-joint-expanded-window-audit-20261011.json'];a,b,c=[json.loads(x.read_text()) for x in refs];expected=[a['pixel_counts'],b['results'][0]['pixel_counts'],c['results'][0]['pixel_counts']];results=[]
 for plan,row,counts_expected in zip(r['plan'],r['results'],expected):
  assert row['baseline_index']==plan['baseline_index'] and row['returncode']==0 and row['status']=='supported';assert row['command'][-6:]==[plan['left'],plan['right'],row['command'][-4],'640',str(plan['source_tolerance']),str(plan['window_radius'])];assert sha(row['log'])==row['log_sha256'];assert Path(row['log']).read_text()==row['stdout']+row['stderr'];pins[row['log']]=row['log_sha256'];v=json.loads(row['stdout']);assert v['supported'] and v['attempts']==25 and v['managed_used']==0 and v['geometry_inliers']>=10
  counts=[tuple(map(int,x)) for x in re.findall(r'sites: (\d+), valid_sites: (\d+), informative_pairs: (\d+), agreeing_pairs: (\d+)',v['pixels'])];assert len(counts)==2 and all(info>=1000 and valid/sites>=.3 and agree/info>=.9 for sites,valid,info,agree in counts);assert counts==[tuple(x) for x in counts_expected]
  rss=re.search(r'(\d+)\s+maximum resident set size',row['stderr']);assert rss;results.append({'baseline_index':plan['baseline_index'],'window_radius':plan['window_radius'],'supported':True,'selected_points':v['selected_points'],'witnesses':v['geometry_inliers'],'hypothesis_bank':v['hypothesis_bank'],'pixel_counts':counts,'elapsed_seconds':row['elapsed_seconds'],'max_rss_bytes':int(rss[1]),'managed_peak':v['managed_peak']})
 pins.update({str(x):sha(x) for x in [p,mp,gp,runtime,Path(__file__)]+refs});out=D/'dedup-model-bank-qualified-native-audit-20261011.json';assert not out.exists();out.write_text(json.dumps({'status':'verified_three_real_cpu_pixel_qualified_bank_positives','pins':pins,'results':results,'scope':'Same source as98 generic tests, actual CPU25-bank inference and per-candidate original pixels. Explicit windows2/2/6,filter12,1m; no automatic window selection/semantic precision/collection/all458/full500/RSS cap completion.'},indent=2)+'\n');print(json.dumps(results))
if __name__=='__main__':main()
